  }
  if (a === 'post') {
    const row = await makePost(Object.assign({}, b, { videos: b.postVideos, isRequest: true }), r, '');
    if (row) { out.push({ json: Object.assign({ _tab: 'stories' }, row) }); log('Agent', 'Sent post ' + row['Story ID'] + ' for approval: ' + v(r.idea)); }
    return;
  }
  if (a === 'offer') {
    const o = r.offer || {};
    out.push({ json: { _tab: 'offers', 'Branch': v(o.Branch) || b.branch, 'Offer': v(o.Offer), 'Details': v(o.Details), 'Start date': v(o['Start date']), 'End date': v(o['End date']) } });
  }
  const msg = v(r.message) || (a === 'offer' ? '✅ Offer added.' : '');
  if (msg) { await say(msg); log('Agent', msg); }
}

// ---------- Stories: ready Drive video or designed image ----------
async function makeStory(b, r, err) {
  let vid = null;
  if (r && r.type === 'video') vid = (b.videos || []).find((x) => x.key === v(r.video) || x.id === v(r.video)) || null;
  if (!r || (!vid && !r.design)) { await say('⚠️ The content agent failed for ' + b.branch + '.\n' + (err || 'No usable story in the AI answer.')); return null; }

  const id = 'S' + now.toISOString().slice(2, 10).replace(/-/g, '') + Math.random().toString(36).slice(2, 5).toUpperCase();
  const keyboard = { inline_keyboard: [[{ text: '✅ Publish', callback_data: 'st_pub:' + id }, { text: '🔄 Redo', callback_data: 'st_redo:' + id }], [{ text: '⏭ Skip', callback_data: 'st_skip:' + id }]] };
  let d, url, msgId = '', status = 'Waiting for Bill';
  const head = (b.isRedo ? '🔄 New version' : b.isRequest ? '🆕 Your story' : '🆕 Today\'s story') + ' – ' + b.branch;
  const tail = '\n\n💡 ' + v(r.idea) + (v(r.lesson) ? '\n\n📈 ' + v(r.lesson) : '') + '\n\n✍️ Reply to this message to ask for a change.\nStory: ' + id;

  if (vid) {
    d = { type: 'video', driveId: vid.id, name: vid.name };
    url = 'https://drive.usercontent.google.com/download?id=' + vid.id + '&export=download&confirm=t';
    const caption = head + '\n🎬 Ready video from Drive: ' + vid.name + tail;
    try {
      const m = await tg('sendVideo', { chat_id: s.TELEGRAM_CHAT_ID, video: url, caption: caption.slice(0, 1000), supports_streaming: true, reply_markup: keyboard });
      msgId = String(m.result.message_id);
    } catch (e) {
      try {
        const m = await tg('sendPhoto', { chat_id: s.TELEGRAM_CHAT_ID, photo: vid.thumb, caption: (caption + '\n▶️ Watch: https://drive.google.com/file/d/' + vid.id + '/view').slice(0, 1000), reply_markup: keyboard });
        msgId = String(m.result.message_id);
      } catch (e2) {
        status = 'Telegram failed';
        await say('⚠️ Could not send the story to Telegram. Video: https://drive.google.com/file/d/' + vid.id + '/view\nStory: ' + id);
      }
    }
  } else {
    d = r.design;
    const src = photoFor(b, d.photo);
    if (!src) { await say('⚠️ The agent chose a photo that does not exist (' + v(d.photo) + '). Nothing was made. Press Redo or ask again.'); return null; }
    d.photo = src;
    d.branch_label = b.branchLabel;
    d.phone = b.phone;
    url = s.RENDER_URL + '?k=' + s.RENDER_KEY + '&d=' + Buffer.from(JSON.stringify(d), 'utf8').toString('base64url');
    let renderErr = '';
    try { await H.httpRequest({ url, encoding: 'arraybuffer', timeout: 60000 }); } catch (e) { renderErr = e.message; }
    if (renderErr) {
      status = 'Image failed';
      await say('⚠️ The story image could not be made (' + renderErr + ').\nStory: ' + id);
    } else {
      try {
        const m = await tg('sendPhoto', { chat_id: s.TELEGRAM_CHAT_ID, photo: url, caption: (head + '\n🎨 Designed story' + tail).slice(0, 1000), reply_markup: keyboard });
        msgId = String(m.result.message_id);
      } catch (e) {
        status = 'Telegram failed';
        await say('⚠️ Could not send the story photo to Telegram. Image: ' + url + '\nStory: ' + id);
      }
    }
  }
  return {
    'Story ID': id, 'Date': stamp, 'Branch': b.branch, 'Status': status,
    'Idea (why this story)': v(r.idea), 'Design (JSON)': JSON.stringify(d), 'Image link': url,
    'Telegram message ID': msgId, 'Instagram story ID': '', 'Facebook story ID': '',
    'Reach': '', 'Replies': '', 'Bill feedback': '', 'Lesson learned': v(r.lesson),
    'Format': vid ? 'Story (video)' : 'Story (designed)', 'Caption': ''
  };
}

// ---------- Feed posts: reel from Drive, designed photo post, or carousel ----------
async function makePost(b, r, err) {
  if (!r) { await say('⚠️ The content agent failed to make a post for ' + b.branch + '.\n' + err); return null; }
  const pf = ['reel', 'photo', 'carousel'].includes(r.format) ? r.format : 'photo';
  const id = 'P' + now.toISOString().slice(2, 10).replace(/-/g, '') + Math.random().toString(36).slice(2, 5).toUpperCase();
  const keyboard = { inline_keyboard: [[{ text: '✅ Publish', callback_data: 'st_pub:' + id }, { text: '🔄 Redo', callback_data: 'st_redo:' + id }], [{ text: '⏭ Skip', callback_data: 'st_skip:' + id }]] };
  const caption = v(r.caption);
  const head = (b.isRedo ? '🔄 New version' : b.isRequest ? '🆕 Your post' : '🆕 New post') + ' – ' + b.branch;
  let badPhoto = '';
  const fixSpec = (x) => {
    const d = Object.assign({}, x || {});
    const src = photoFor(b, d.photo);
    if (!src) badPhoto = v(d.photo);
    d.photo = src || '';
    d.format = 'post'; d.branch_label = b.branchLabel; d.phone = b.phone;
    return d;
  };
  const render = (spec) => s.RENDER_URL + '?k=' + s.RENDER_KEY + '&d=' + Buffer.from(JSON.stringify(spec), 'utf8').toString('base64url');
  let d, link, label, status = 'Waiting for Bill';
  if (pf === 'reel') {
    const vid = (b.videos || []).find((x) => x.key === v(r.video) || x.id === v(r.video));
    if (!vid) { await say('⚠️ The agent chose a reel that is not in the list (' + v(r.video) + '). Press Redo on the next one or try again.'); return null; }
    d = { kind: 'post', pf, type: 'video', driveId: vid.id, name: vid.name };
    link = 'https://drive.usercontent.google.com/download?id=' + vid.id + '&export=download&confirm=t';
    label = '🎬 Reel from Drive: ' + vid.name;
    try { await tg('sendVideo', { chat_id: s.TELEGRAM_CHAT_ID, video: link, caption: head + ' · Post: ' + id, supports_streaming: true }); }
    catch (e) {
      try { await tg('sendPhoto', { chat_id: s.TELEGRAM_CHAT_ID, photo: vid.thumb, caption: head + ' · Post: ' + id + '\n▶️ Watch: https://drive.google.com/file/d/' + vid.id + '/view' }); } catch (e2) {}
    }
  } else if (pf === 'carousel') {
    const slides = (Array.isArray(r.slides) ? r.slides : []).slice(0, 5).map(fixSpec);
    if (badPhoto) { await say('⚠️ The agent chose a photo that does not exist (' + badPhoto + '). Nothing was made. Ask again.'); return null; }
    if (slides.length < 2) { await say('⚠️ The carousel came back with less than 2 slides. Press Redo or try again.'); return null; }
    const urls = slides.map(render);
    for (const u of urls) { try { await H.httpRequest({ url: u, encoding: 'arraybuffer', timeout: 60000 }); } catch (e) { status = 'Image failed'; } }
    d = { kind: 'post', pf, slides, urls };
    link = urls.join('\n');
    label = '🖼 Carousel: ' + urls.length + ' slides';
    try { await tg('sendMediaGroup', { chat_id: s.TELEGRAM_CHAT_ID, media: urls.map((u, k) => (k === 0 ? { type: 'photo', media: u, caption: head + ' · Post: ' + id } : { type: 'photo', media: u })) }); }
    catch (e) { await say('⚠️ Could not show the carousel slides in Telegram.'); }
  } else {
    const spec = fixSpec(r.design);
    if (badPhoto) { await say('⚠️ The agent chose a photo that does not exist (' + badPhoto + '). Nothing was made. Ask again.'); return null; }
    link = render(spec);
    try { await H.httpRequest({ url: link, encoding: 'arraybuffer', timeout: 60000 }); } catch (e) { status = 'Image failed'; }
    d = { kind: 'post', pf, spec };
    label = '📷 Photo post';
    try { await tg('sendPhoto', { chat_id: s.TELEGRAM_CHAT_ID, photo: link, caption: head + ' · Post: ' + id }); } catch (e) { await say('⚠️ Could not show the image in Telegram: ' + link); }
  }
  const ctrl = head + '\n' + label + '\n\n📝 Caption:\n' + caption + '\n\n💡 ' + v(r.idea) + (v(r.lesson) ? '\n\n📈 ' + v(r.lesson) : '') +
    '\n\n✍️ Reply to this message to ask for a change.\nPost: ' + id;
  let msgId = '';
  try { const m = await tg('sendMessage', { chat_id: s.TELEGRAM_CHAT_ID, text: ctrl.slice(0, 4000), reply_markup: keyboard }); msgId = String(m.result.message_id); }
  catch (e) { status = 'Telegram failed'; }
  return {
    'Story ID': id, 'Date': stamp, 'Branch': b.branch, 'Status': status,
    'Idea (why this story)': v(r.idea), 'Design (JSON)': JSON.stringify(d), 'Image link': link,
    'Telegram message ID': msgId, 'Instagram story ID': '', 'Facebook story ID': '',
    'Reach': '', 'Replies': '', 'Bill feedback': '', 'Lesson learned': v(r.lesson),
    'Format': pf === 'reel' ? 'Reel' : pf === 'carousel' ? 'Carousel' : 'Photo post', 'Caption': caption
  };
}
